-- ============================================================================
-- Legacy attendance import: replace the demo attendance rows with the
-- previous system's real records.
--
-- Kept only: rows with a REAL time in and time out (the dump's broken
-- zero-date rows and rows missing a time out are left out), rows whose
-- library card exists in the new system, and student visits that have their
-- enrollment on record (the schema requires it) with a known year level.
-- Visit dates map to their semester; purposes fold into the system's five
-- standard purposes. The previous system kept no operator, so the importing
-- admin is stored as the recorder and the checker-outer.
-- ============================================================================

-- 1) Clear the demo rows (and their log lines) ------------------------------
alter table public.attendance disable trigger guard_attendance;
alter table public.attendance disable trigger activity_capture;
alter table public.activity_events disable trigger activity_events_append_only;

delete from public.activity_events
 where entity_type = 'attendance' or action like 'attendance.%';
delete from public.attendance;

alter table public.activity_events enable trigger activity_events_append_only;

-- 2) Import the complete, matched legacy rows -------------------------------
insert into public.attendance
  (user_profile_id, semester_id, purpose_of_visit, role_at_visit,
   student_enrollment_id, year_level, year_level_note,
   time_in, time_out, created_at, recorded_by, checked_out_by, provenance)
select
  u.id,
  s.id,
  case lower(btrim(l.purpose_of_visit))
    when 'study' then 'Studying'
    when 'research' then 'Research'
    when 'thesis' then 'Research'
    when 'borrow books' then 'Borrowing/Returning'
    when 'return books' then 'Borrowing/Returning'
    else 'Other'
  end,
  lower(btrim(u.role::text)),
  e.id,
  case
    when lower(btrim(u.role::text)) = 'student'
     and lower(btrim(l.year_level)) in
         ('1st year', '2nd year', '3rd year', '4th year', '5th year')
    then left(btrim(l.year_level), 1)::smallint
    else null
  end,
  case when lower(btrim(l.year_level)) = '5th year'
       then 'Legacy record: 5th Year' else null end,
  (l.time_in::timestamp) at time zone 'Asia/Manila',
  (l.time_out::timestamp) at time zone 'Asia/Manila',
  (l.time_in::timestamp) at time zone 'Asia/Manila',
  adm.id,
  adm.id,
  'import'
from legacy_attendance l
join public."usersData" u on u.library_id = btrim(l.user_id)
left join public.semesters s
  on (l.time_in::timestamp)::date between s.starts_on and s.ends_on
left join public.student_enrollments e
  on e.user_profile_id = u.id and e.academic_year_id = s.academic_year_id
cross join (
  select id from public."usersData"
   where lower(btrim(role::text)) = 'admin'
   order by id limit 1) adm
where l.time_in ~ '^2\d{3}-' and l.time_out ~ '^2\d{3}-'
  and (
    lower(btrim(u.role::text)) <> 'student'
    or (
      e.id is not null
      and lower(btrim(l.year_level)) in
          ('1st year', '2nd year', '3rd year', '4th year', '5th year')
    )
  );

alter table public.attendance enable trigger guard_attendance;
alter table public.attendance enable trigger activity_capture;

-- 3) Record the import in the provenance ledger -----------------------------
insert into public.provenance_batches
  (label, table_name, criteria, row_count, actor, note)
select
  'import',
  'attendance',
  'Legacy attendance import (previous system) — attendance_records.sql (improved_lms MariaDB dump): complete rows only (real time in and time out), matched library cards, student visits with their enrollment on record, visit dates mapped to their semester; the previous system kept no operator, so the importing admin is stored as the recorder and checker-outer',
  count(*),
  (select concat_ws(' ', first_name, surname) from public."usersData"
    where lower(btrim(role::text)) = 'admin' order by id limit 1),
  'Replaces the removed demo/seed attendance rows. Source dump generated 14 Oct 2026.'
from public.attendance;

update public.provenance_batches
   set note = coalesce(note, '') ||
              ' [Demo rows removed 15 Oct 2026 — replaced by the legacy import.]'
 where table_name = 'attendance'
   and id <> (select max(id) from public.provenance_batches
               where table_name = 'attendance');

select 'legacy.complete_rows' as check,
       count(*)::text as value
from legacy_attendance
where time_in ~ '^2\d{3}-' and time_out ~ '^2\d{3}-'
union all
select 'legacy.left_out_incomplete',
       count(*)::text
from legacy_attendance
where time_in !~ '^2\d{3}-' or time_out is null or time_out !~ '^2\d{3}-'
union all
select 'excluded.unmatched_users',
       count(*)::text
from legacy_attendance l
where l.time_in ~ '^2\d{3}-' and l.time_out ~ '^2\d{3}-'
  and not exists (select 1 from public."usersData" u
                   where u.library_id = btrim(l.user_id))
union all
select 'excluded.student_without_enrollment',
       count(*)::text
from legacy_attendance l
join public."usersData" u on u.library_id = btrim(l.user_id)
where l.time_in ~ '^2\d{3}-' and l.time_out ~ '^2\d{3}-'
  and lower(btrim(u.role::text)) = 'student'
  and not exists (
    select 1
    from public.semesters s
    join public.student_enrollments e
      on e.academic_year_id = s.academic_year_id
     and e.user_profile_id = u.id
    where (l.time_in::timestamp)::date between s.starts_on and s.ends_on)
union all
select 'excluded.student_without_year_level',
       count(*)::text
from legacy_attendance l
join public."usersData" u on u.library_id = btrim(l.user_id)
where l.time_in ~ '^2\d{3}-' and l.time_out ~ '^2\d{3}-'
  and lower(btrim(u.role::text)) = 'student'
  and lower(btrim(l.year_level)) not in
      ('1st year', '2nd year', '3rd year', '4th year', '5th year')
union all
select 'imported.rows', count(*)::text from public.attendance
union all
select 'imported.sem_2025_2026_2',
       count(*)::text
from public.attendance a
join public.semesters s on s.id = a.semester_id
where s.starts_on = '2026-01-16'
union all
select 'imported.sem_2026_2027_1',
       count(*)::text
from public.attendance a
join public.semesters s on s.id = a.semester_id
where s.starts_on = '2026-07-01'
union all
select 'imported.linked_enrollment',
       count(*)::text
from public.attendance where student_enrollment_id is not null
union all
select 'imported.students',
       count(*)::text
from public.attendance where role_at_visit = 'student'
union all
select 'imported.nonstudents',
       count(*)::text
from public.attendance where role_at_visit <> 'student'
union all
select 'imported.recorded_by_set',
       count(*)::text
from public.attendance where recorded_by is not null
union all
select 'imported.purposes',
       string_agg(purpose_of_visit || ' x' || n, ' | ' order by n desc)
from (select purpose_of_visit, count(*) n from public.attendance group by 1) p
union all
select 'sample.first_visit',
       coalesce((select u.library_id || ' | ' || a.purpose_of_visit || ' | ' ||
                        to_char(a.time_in at time zone 'Asia/Manila',
                                'Mon DD, YYYY HH12:MI AM')
                   from public.attendance a
                   join public."usersData" u on u.id = a.user_profile_id
                  order by a.time_in limit 1), 'none')
union all
select 'sample.last_visit',
       coalesce((select u.library_id || ' | ' || a.purpose_of_visit || ' | ' ||
                        to_char(a.time_in at time zone 'Asia/Manila',
                                'Mon DD, YYYY HH12:MI AM')
                   from public.attendance a
                   join public."usersData" u on u.id = a.user_profile_id
                  order by a.time_in desc limit 1), 'none')
union all
select 'activity_events.attendance_left',
       count(*)::text
from public.activity_events
where entity_type = 'attendance' or action like 'attendance.%';

commit;
